const packet = $('Soạn Thư Mời & Tổng Hợp Packet').first().json;
const backendSyncResult = $json;

return [{
  json: {
    success: true,
    action: "INTERVIEW_ORCHESTRATED_AND_SYNCED",
    candidateId: packet.candidateId,
    candidateName: packet.candidateName,
    candidateEmail: packet.candidateEmail,
    jobTitle: packet.jobTitle,
    companyName: packet.companyName,
    interviewType: packet.interviewType,
    schedule: {
      time: packet.dateTimeFormatted,
      location: packet.locationText,
      googleMeetUrl: packet.googleMeetUrl,
      isRealGoogleMeet: packet.isRealGoogleMeet,
      googleCalendarEventId: packet.googleCalendarEventId,
      googleCalendarHtmlLink: packet.googleCalendarHtmlLink,
      officeAddress: packet.officeAddress,
      deadline: packet.deadlineFormatted,
      calendarIcsAttached: true
    },
    interviewerPanel: packet.leadInterviewer,
    contactPerson: packet.contactPerson,
    backendSync: {
      status: backendSyncResult?.id ? "SYNCED_TO_DATABASE" : "STANDALONE_SIMULATED",
      updatedCandidateId: backendSyncResult?.id || packet.candidateId
    },
    orchestratedAt: new Date().toISOString()
  }
}];
